+import { ResourceManagementClient } from "@azure/arm-resources";
+import { DefaultAzureCredential } from "@azure/identity";
+
+const subscriptionId = process.env.AZURE_SUBSCRIPTION_ID;
+const resourceGroupName = process.env.AZURE_RESOURCE_GROUP_NAME;
+
+if (!subscriptionId) {
+  throw new Error("AZURE_SUBSCRIPTION_ID environment variable is required.");
+}
+
+if (!resourceGroupName) {
+  throw new Error("AZURE_RESOURCE_GROUP_NAME environment variable is required.");
+}
+
+async function main(): Promise<void> {
+  const credential = new DefaultAzureCredential();
+  const client = new ResourceManagementClient(credential, subscriptionId);
+  let resourceGroupCreated = false;
+
+  try {
+    console.log(`Creating resource group "${resourceGroupName}" in eastus...`);
+    const createdResourceGroup = await client.resourceGroups.createOrUpdate(
+      resourceGroupName,
+      { location: "eastus" },
+    );
+    resourceGroupCreated = true;
+    console.log("Created:", createdResourceGroup);
+
+    console.log("\nResource groups in the subscription:");
+    for await (const resourceGroup of client.resourceGroups.list()) {
+      console.log(`- ${resourceGroup.name} (${resourceGroup.location})`);
+    }
+
+    const resourceGroup = await client.resourceGroups.get(resourceGroupName);
+    console.log("\nCreated resource group details:", resourceGroup);
+
+    const updatedResourceGroup = await client.resourceGroups.update(
+      resourceGroupName,
+      {
+        tags: {
+          ...resourceGroup.tags,
+          managedBy: "typescript-sdk-sample",
+        },
+      },
+    );
+    console.log("\nUpdated resource group:", updatedResourceGroup);
+  } finally {
+    if (resourceGroupCreated) {
+      console.log(`\nDeleting resource group "${resourceGroupName}"...`);
+      await client.resourceGroups.beginDeleteAndWait(resourceGroupName);
+      console.log("Resource group deleted.");
+    }
+  }
+}
+
+main().catch((error: unknown) => {
+  console.error("Resource group operation failed:", error);
+  process.exitCode = 1;
+});
*** Add File: README.md
+# Azure Resource Group management with TypeScript
+
+This sample uses the Azure management plane SDK to create, list, retrieve,
+tag, and delete a resource group. The resource group is deleted in a `finally`
+block so cleanup is attempted even if a later operation fails.
+
+## Install
+
+```powershell
+npm install
+```
+
+Required runtime packages:
+
+```powershell
+npm install @azure/identity @azure/arm-resources
+```
+
+The sample also uses TypeScript, `tsx`, and Node.js type declarations for local
+development:
+
+```powershell
+npm install --save-dev typescript tsx @types/node
+```
+
+## Configure and run
+
+Set the subscription and the name of the temporary resource group. Do not put
+credentials in source code.
+
+```powershell
+$env:AZURE_SUBSCRIPTION_ID = "<subscription-id>"
+$env:AZURE_RESOURCE_GROUP_NAME = "<unique-resource-group-name>"
+npm start
+```
+
+`DefaultAzureCredential` can use a supported local developer login or
+environment-based service principal credentials. In Azure-hosted production
+workloads, use a managed identity and grant only the management-plane RBAC
+permissions needed to manage the target resource group.
+
+> **Warning:** Running the sample creates and then deletes a real Azure resource
+> group. Deleting a resource group also deletes every resource it contains. Use
+> a new, disposable resource group name.
